// "spec fn" in the prompt is a verification-only construct; here we provide a
// normal Rust function with the same intent.
fn is_2_pow(n: i128) -> bool {
    if n <= 0 {
        return false;
    }
    let mut v = n;
    while v % 2 == 0 {
        v /= 2;
    }
    v == 1
}

/// Returns the lower-bound insertion index of `x` within `a[lo..hi)`.
/// That is, it returns `k` such that:
/// - for all r in [lo, k): a[r] < x
/// - for all r in [k, hi): a[r] >= x
///
/// Assumes `a[lo..hi)` is sorted in nondecreasing order.
fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    debug_assert!(lo <= hi);
    debug_assert!(hi <= a.len());

    let mut left = lo;
    let mut right = hi; // invariant: answer in [left, right]

    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] < x {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    left
}

/// Returns the lower-bound insertion index of `x` within the first 1000 elements
/// of `a` (i.e., in `a[0..1000)`).
///
/// Assumes `a.len() >= 1000` and `a[0..1000)` is sorted in nondecreasing order.
fn search_1000(a: &[i32], x: i32) -> usize {
    assert!(a.len() >= 1000);
    search_range_helper(a, x, 0, 1000)
}